const api=OwaysAPI.request,E=OwaysAPI.escape,$=s=>document.querySelector(s),params=new URLSearchParams(location.search);let user,challenge,loginData,catalogData;let authMode='login';const states={review:'قيد المراجعة',awaiting_customer:'بانتظار إجراء منك',ready:'جاهز للتنفيذ',processing:'قيد التنفيذ',completed:'مكتمل',cancelled:'ملغي',draft:'مسودة',awaiting_payment:'بانتظار الدفع',not_required_yet:'بانتظار عرض السعر',verification:'قيد التحقق',paid:'مدفوع'};function status(s){$('#status').textContent=s;if(!$('#auth-panel').hidden){$('#auth-feedback').hidden=!s;$('#auth-feedback-text').textContent=s;$('#auth-feedback-action').hidden=true}}async function run(fn){try{await fn()}catch(e){status(e.message);if(!$('#auth-panel').hidden){$('#auth-feedback').classList.add('error');const signup=e.message.includes('لا يوجد حساب بهذا الرقم'),login=e.message.includes('يوجد حساب بهذا الرقم')&&!signup;if(signup||login){const action=$('#auth-feedback-action');action.hidden=false;action.textContent=signup?'إنشاء حساب بهذا الرقم ←':'تسجيل الدخول بهذا الرقم ←';action.onclick=()=>{selectAuthMode(signup?'signup':'login');if(signup)$('#full-name-field input').focus();else $('#phone-number').focus()}}}}}
$('#login').onsubmit=e=>{e.preventDefault();run(async()=>{loginData={...Object.fromEntries(new FormData(e.target)),auth_mode:authMode};loginData.phone=internationalPhone();loginData.remember=e.target.elements.remember.checked;delete loginData.national_phone;challenge=await api('/api/auth/request',loginData);$('#verify-phone').textContent='أدخل الرمز الخاص بالرقم '+loginData.phone;$('#verify').hidden=false;$('#login').hidden=true;$('.auth-mode-switch').hidden=true;status(challenge.delivery==='local_terminal'?'وضع التطوير المحلي: اقرأ رمز التحقق من طرفية الخادم.':'أُرسل رمز التحقق إلى رقمك.');$('#verify input').focus()})};$('#change-number').onclick=()=>{$('#login').hidden=false;$('#verify').hidden=true;$('.auth-mode-switch').hidden=false;$('#verify').reset()};$('#verify').onsubmit=e=>{e.preventDefault();run(async()=>{const r=await api('/api/auth/verify',{...loginData,challenge_id:challenge.challenge_id,code:new FormData(e.target).get('code')});user=r.user;window.dispatchEvent(new CustomEvent('oways:session',{detail:user}));await member()})};
async function member(){if(user.role==='admin'){location.replace('/admin');return}$('#auth-panel').hidden=true;$('#member').hidden=false;$('#welcome').textContent='مرحبًا '+user.full_name;$('#admin-link').hidden=user.role!=='admin';status('');await listOrders();if(params.get('intent')==='support'){$('#support-panel').hidden=false;$('#support-reason').value=params.get('reason')||'استفسار عام'}if(params.get('service')){catalogData=await api('/api/catalog');const s=catalogData.services.find(s=>s.slug===params.get('service'));if(!s){$('#selection').hidden=false;$('#selection').textContent='هذه الخدمة لم تُضَف إلى كتالوج الإدارة بعد. يمكن للدعم مساعدتك.';$('#support-panel').hidden=false;$('#support-reason').value='أرغب في الخدمة: '+params.get('service');return}renderSelection(s)}}
function renderSelection(s){const panel=$('#selection');panel.hidden=false;panel.innerHTML=`<h2>${E(s.name)}</h2><label>اختر الباقة<select id="package">${s.packages.map(p=>`<option value="${E(p.id)}">${E(p.name)} — ${p.price===null?'عرض سعر':E(p.price)+' '+E(p.currency)}</option>`).join('')}</select></label><div id="requirements"></div>`;if(!s.packages.length){$('#requirements').textContent='لا توجد باقة متاحة حاليًا.';return}function fields(){const p=s.packages.find(p=>String(p.id)===$('#package').value);$('#requirements').innerHTML=`${p.instructions.filter(i=>i.stage==='before_order').map(i=>`<p class="portal-note">${E(i.body)}</p>`).join('')}<form id="order-form">${p.requirements.map(r=>`<label>${E(r.label)}${r.required?' *':''}${r.input_type==='select'?`<select name="${E(r.field_key)}" ${r.required?'required':''}><option value="">اختر</option>${(r.options_json||[]).map(v=>`<option>${E(v)}</option>`).join('')}</select>`:r.input_type==='textarea'?`<textarea name="${E(r.field_key)}" ${r.required?'required':''} maxlength="4000"></textarea>`:`<input name="${E(r.field_key)}" type="${({phone:'tel',number:'number',file:'text'})[r.input_type]||E(r.input_type)}" ${r.required?'required':''} maxlength="4000">`}<small>${E(r.help_text||'')}</small></label>`).join('')}<button class="button">حفظ الطلب والتواصل مع الدعم ←</button><p class="fine">الطلب لا يؤكد الدفع أو التفعيل.</p></form>`;$('#order-form').onsubmit=e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;run(async()=>{const o=await api('/api/orders',{package_id:p.id,answers:Object.fromEntries(new FormData(e.target))});panel.innerHTML=`<h2>تم حفظ طلبك ${E(o.public_reference)}</h2><p>يمكنك متابعة الطلب من حسابك.</p>`;await listOrders();await support({order_id:o.id})}).finally(()=>button.disabled=false)}}$('#package').onchange=fields;fields()}
async function listOrders(){const r=await api('/api/orders');$('#orders').innerHTML=r.orders.length?r.orders.map(o=>`<article class="portal-row"><div><b>${E(o.public_reference)}</b><small>${E(states[o.fulfillment_status]||o.fulfillment_status)} · ${E(states[o.payment_status]||o.payment_status)}</small></div><button class="button outline" data-details="${E(o.id)}">تفاصيل الطلب</button></article>`).join(''):'<p>لا توجد طلبات بعد. اختر خدمة من الصفحة الرئيسية.</p>'}
async function detail(id){const o=await api('/api/orders/'+id);$('#details').hidden=false;$('#details').innerHTML=`<h2>${E(o.public_reference)}</h2>${o.items.map(i=>`<h3>${E(i.package_snapshot.service_name)} — ${E(i.package_snapshot.name)}</h3><p>${E(states[i.fulfillment_status]||i.fulfillment_status)}</p>`).join('')}${o.updates.map(u=>`<p class="portal-note">${E(u.body)}</p>`).join('')}<button class="button" data-support="${E(o.id)}">متابعة الطلب مع الدعم ↗</button>`;$('#details').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}
async function support(data){const r=await api('/api/support',data);$('#message-text').value=r.message;$('#whatsapp-link').hidden=!r.url;$('#no-whatsapp').hidden=!!r.url;if(r.url)$('#whatsapp-link').href=r.url;$('#support-message').showModal()}$('#general-support').onclick=()=>run(()=>support({reason:$('#support-reason').value}));$('#close-message').onclick=()=>$('#support-message').close();$('#copy-message').onclick=()=>run(async()=>{await navigator.clipboard.writeText($('#message-text').value);status('تم نسخ الرسالة.')});document.addEventListener('click',e=>{const d=e.target.closest('[data-details]'),s=e.target.closest('[data-support]');if(d)run(()=>detail(d.dataset.details));if(s)run(()=>support({order_id:s.dataset.support}))});run(async()=>{try{user=(await api('/api/auth/me')).user}catch(e){if(!e.message.includes('سجّل الدخول')&&!e.message.includes('انتهت الجلسة'))throw e}if(user)await member()});

function selectAuthMode(mode){authMode=mode;const signup=mode==='signup';$('#full-name-field').hidden=!signup;const name=$('#full-name-field input');name.disabled=!signup;name.required=signup;$('#login').classList.toggle('login-mode',!signup);$('#mode-login').classList.toggle('selected',!signup);$('#mode-signup').classList.toggle('selected',signup);$('#mode-login').setAttribute('aria-pressed',String(!signup));$('#mode-signup').setAttribute('aria-pressed',String(signup));$('#auth-title').textContent=signup?'إنشاء حساب':'تسجيل الدخول';$('#auth-help').textContent=signup?'أدخل اسمك ورقم هاتفك لإنشاء حساب جديد.':'أدخل رقم هاتفك. لن يُطلب رمز جديد أثناء بقاء جلستك محفوظة.';$('#login button[type="submit"],#login .auth-submit button').textContent=signup?'إنشاء حساب والتحقق ←':'تسجيل الدخول برمز التحقق ←';status('')}
$('#mode-login').onclick=()=>selectAuthMode('login');$('#mode-signup').onclick=()=>selectAuthMode('signup');selectAuthMode(params.get('mode')==='signup'?'signup':'login');

const callingCountries=[['SY','سوريا','963'],['LB','لبنان','961'],['JO','الأردن','962'],['IQ','العراق','964'],['SA','السعودية','966'],['AE','الإمارات','971'],['KW','الكويت','965'],['QA','قطر','974'],['BH','البحرين','973'],['OM','عُمان','968'],['YE','اليمن','967'],['PS','فلسطين','970'],['EG','مصر','20'],['SD','السودان','249'],['LY','ليبيا','218'],['TN','تونس','216'],['DZ','الجزائر','213'],['MA','المغرب','212'],['TR','تركيا','90'],['DE','ألمانيا','49'],['NL','هولندا','31'],['RO','رومانيا','40'],['FR','فرنسا','33'],['GB','المملكة المتحدة','44'],['US','الولايات المتحدة','1'],['CA','كندا','1'],['AU','أستراليا','61'],['OTHER','مفتاح آخر','']];
$('#country-code').innerHTML=callingCountries.map(([iso,name,code])=>'<option value="'+iso+'">'+name+(code?' (+'+code+')':'')+'</option>').join('');
let suggested='';for(const language of navigator.languages||[navigator.language]){try{const region=new Intl.Locale(language).region;if(callingCountries.some(c=>c[0]===region)){suggested=region;break}}catch{}}
$('#country-code').value=suggested||'SY';$('#country-hint').textContent=suggested?'اختيار مبدئي حسب لغة المتصفح؛ عدّله إذا لزم.':'اختر الدولة الصحيحة لرقمك.';
const customLabel=document.createElement('label');customLabel.className='custom-calling-code';customLabel.hidden=true;customLabel.innerHTML='مفتاح الدولة<input id="custom-country-code" inputmode="numeric" dir="ltr" placeholder="مثال: 39" maxlength="3">';$('.phone-field').append(customLabel);
$('#country-code').onchange=()=>{customLabel.hidden=$('#country-code').value!=='OTHER';$('#country-hint').textContent='أدخل رقمك المحلي، أو الرقم الدولي كاملًا مع +.'};
function internationalPhone(){let number=$('#phone-number').value.trim().replace(/[٠-٩۰-۹]/g,c=>{const n=c.charCodeAt(0);return String(n>=1776?n-1776:n-1632)}).replace(/[\s()-]/g,'');if(number.startsWith('00'))number='+'+number.slice(2);if(number.startsWith('+')){if(!/^\+[1-9]\d{7,14}$/.test(number))throw Error('رقم الهاتف الدولي غير صالح.');return number}const country=callingCountries.find(c=>c[0]===$('#country-code').value);const code=country[0]==='OTHER'?$('#custom-country-code').value.trim().replace(/^\+/,''):country[2];if(!/^[1-9]\d{0,2}$/.test(code))throw Error('مفتاح الدولة غير صالح.');if(country[0]!=='OTHER')number=number.replace(/^0+/,'');const full='+'+code+number;if(!/^\+[1-9]\d{7,14}$/.test(full))throw Error('تحقق من مفتاح الدولة ورقم الهاتف.');return full}
